//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::uint::usize_mod`; the
//! native twin is `benches/native/Bench/UsizeMod.lean`.

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::uint;
use lean_runtime_bench::{run, step, SEED};

#[allow(unused_variables)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = acc.wrapping_add(uint::usize_mod((x) as usize, (x.rotate_left(17)) as usize) as u64);
    }
    acc as u64
}

fn main() {
    run(|| (), kernel)
}
